"use client";

import React, { useState } from "react";
import * as LucideIcons from "lucide-react";
import { Button } from "../../../components/ui/Button";
import { Input } from "../../../components/ui/Input";

// Safe icon renderer
function Icon({ name, className }: { name: string, className?: string }) {
    const LucideIcon = (LucideIcons as any)[name];
    if (!LucideIcon) return <div className={className} style={{ width: '20px', height: '20px', backgroundColor: '#333', borderRadius: '4px' }} />;
    return <LucideIcon className={className} />;
}

export default function AdminFinanceiro() {
    const [activeTab, setActiveTab] = useState<'overview' | 'config' | 'reports'>('overview');
    const [isExpenseModalOpen, setIsExpenseModalOpen] = useState(false);

    // Virgin transactions
    const [transactions, setTransactions] = useState<any[]>([]);

    const [expenseName, setExpenseName] = useState("");
    const [expenseValue, setExpenseValue] = useState("");

    // Config States
    const [monthlyGoal, setMonthlyGoal] = useState("0");
    const [globalCommission, setGlobalCommission] = useState("50");

    const addExpense = (e: React.FormEvent) => {
        e.preventDefault();
        if (!expenseName || !expenseValue) return;

        const newTransaction = {
            id: Date.now(),
            label: expenseName,
            time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
            value: parseFloat(expenseValue),
            type: "expense" as const
        };

        setTransactions([newTransaction, ...transactions]);
        setExpenseName("");
        setExpenseValue("");
        setIsExpenseModalOpen(false);
    };

    const totalIncome = transactions.filter(t => t.type === 'income').reduce((acc, t) => acc + t.value, 0);
    const totalExpense = transactions.filter(t => t.type === 'expense').reduce((acc, t) => acc + t.value, 0);
    const balance = totalIncome - totalExpense;
    const goalVal = parseFloat(monthlyGoal) || 0;
    const goalProgress = goalVal > 0 ? (balance / goalVal) * 100 : 0;

    return (
        <div className="min-h-screen bg-[#0a0a0a] text-white p-6 lg:p-12 font-sans selection:bg-[#D4AF37] selection:text-black animate-fade-in-up">
            <div className="max-w-6xl mx-auto flex flex-col gap-8">
                <header className="flex flex-col md:flex-row md:items-center justify-between gap-6">
                    <div>
                        <h1 className="text-3xl font-semibold mb-1">
                            Gestão <span className="text-[#D4AF37]">Financeira</span>
                        </h1>
                        <p className="text-gray-400 text-sm">Controle completo de caixa, metas e comissões</p>
                    </div>
                    <div className="flex bg-[#111111] p-1 rounded-2xl border border-[#1f1f1f]">
                        <button onClick={() => setActiveTab('overview')} className={`px-6 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'overview' ? 'bg-[#D4AF37] text-black shadow-lg' : 'text-gray-500 hover:text-white'}`}>Painel</button>
                        <button onClick={() => setActiveTab('config')} className={`px-6 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'config' ? 'bg-[#D4AF37] text-black shadow-lg' : 'text-gray-500 hover:text-white'}`}>Configurações</button>
                    </div>
                </header>

                {activeTab === 'overview' ? (
                    <div className="animate-fade-in-up space-y-8">
                        <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
                            <div className="bg-[#111111] border border-[#1f1f1f] p-8 rounded-3xl shadow-xl">
                                <p className="text-[9px] font-black text-emerald-500 uppercase tracking-widest mb-4">Receitas</p>
                                <h3 className="text-3xl font-bold tracking-tighter">R$ {totalIncome.toLocaleString('pt-BR')}</h3>
                            </div>
                            <div className="bg-[#111111] border border-[#1f1f1f] p-8 rounded-3xl shadow-xl">
                                <p className="text-[9px] font-black text-red-500 uppercase tracking-widest mb-4">Despesas</p>
                                <h3 className="text-3xl font-bold tracking-tighter">R$ {totalExpense.toLocaleString('pt-BR')}</h3>
                            </div>
                            <div className="bg-[#111111] border border-[#1f1f1f] p-8 rounded-3xl shadow-xl">
                                <p className="text-[9px] font-black text-[#D4AF37] uppercase tracking-widest mb-4">Saldo Líquido</p>
                                <h3 className="text-3xl font-bold tracking-tighter">R$ {balance.toLocaleString('pt-BR')}</h3>
                            </div>
                            <div className="bg-[#111111] border border-[#D4AF37]/20 p-8 rounded-3xl shadow-xl">
                                <p className="text-[9px] font-black text-white/40 uppercase tracking-widest mb-4 flex justify-between items-center">Meta Mensal <span className="text-[#D4AF37]">{Math.round(goalProgress)}%</span></p>
                                <div className="h-2 w-full bg-[#1a1a1a] rounded-full overflow-hidden mb-4">
                                    <div className="h-full bg-[#D4AF37] shadow-[0_0_10px_rgba(212,175,55,0.4)]" style={{ width: `${Math.min(goalProgress, 100)}%` }} />
                                </div>
                                <h3 className="text-xl font-bold text-white/50">R$ {goalVal.toLocaleString('pt-BR')}</h3>
                            </div>
                        </div>

                        <div className="bg-[#111111] border border-[#1f1f1f] rounded-3xl p-8 shadow-xl">
                            <div className="flex items-center justify-between mb-8">
                                <h3 className="text-xl font-bold tracking-tight">Movimentações de Hoje</h3>
                                <Button onClick={() => setIsExpenseModalOpen(true)} size="sm" className="gap-2 bg-red-500/10 text-red-500 border-red-500/20 hover:bg-red-500 hover:text-white">
                                    <Icon name="Plus" className="w-4 h-4" /> Despesa
                                </Button>
                            </div>
                            <div className="space-y-4">
                                {transactions.length > 0 ? transactions.map((t) => (
                                    <div key={t.id} className="bg-[#1a1a1a]/40 border border-[#222] p-5 rounded-2xl flex items-center justify-between group">
                                        <div className="flex items-center gap-6">
                                            <div className={`w-10 h-10 rounded-xl flex items-center justify-center border border-[#222] ${t.type === 'income' ? 'bg-emerald-500/5 text-emerald-500' : 'bg-red-500/5 text-red-500'}`}>
                                                <Icon name={t.type === 'income' ? 'ArrowUp' : 'ArrowDown'} className="w-4 h-4" />
                                            </div>
                                            <div>
                                                <h4 className="font-bold text-sm text-gray-200">{t.label}</h4>
                                                <p className="text-[9px] text-gray-600 font-bold uppercase tracking-widest mt-1">{t.time}</p>
                                            </div>
                                        </div>
                                        <span className={`text-base font-bold tracking-tight ${t.type === 'income' ? 'text-emerald-500' : 'text-red-500'}`}>
                                            {t.type === 'income' ? '+' : '-'} R$ {t.value.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                                        </span>
                                    </div>
                                )) : (
                                    <p className="text-center text-gray-600 italic py-10">Nenhuma movimentação hoje.</p>
                                )}
                            </div>
                        </div>
                    </div>
                ) : (
                    <div className="animate-fade-in-up grid grid-cols-1 lg:grid-cols-2 gap-8">
                        <section className="bg-[#111111] border border-[#1f1f1f] rounded-3xl p-8 space-y-8">
                            <header className="flex items-center gap-3">
                                <Icon name="BarChart2" className="text-[#D4AF37]" />
                                <h3 className="text-xl font-bold">Configurações Base</h3>
                            </header>
                            <div className="space-y-6">
                                <div className="space-y-2">
                                    <label className="text-[10px] uppercase font-black text-gray-500 tracking-widest">Meta de Faturamento Mensal</label>
                                    <div className="relative">
                                        <span className="absolute left-4 top-1/2 -translate-y-1/2 text-[#D4AF37] font-bold">R$</span>
                                        <Input value={monthlyGoal} onChange={(e) => setMonthlyGoal(e.target.value)} className="pl-12 bg-[#1a1a1a] border-[#222]" />
                                    </div>
                                </div>
                                <div className="space-y-2">
                                    <label className="text-[10px] uppercase font-black text-gray-500 tracking-widest">Comissão Global (%)</label>
                                    <Input value={globalCommission} onChange={(e) => setGlobalCommission(e.target.value)} type="number" className="bg-[#1a1a1a] border-[#222]" />
                                </div>
                            </div>
                        </section>

                        <section className="bg-[#111111] border border-[#1f1f1f] rounded-3xl p-8 space-y-8">
                            <header className="flex items-center gap-3">
                                <Icon name="Lock" className="text-red-500" />
                                <h3 className="text-xl font-bold">Segurança e Fechamento</h3>
                            </header>
                            <div className="space-y-6">
                                <div className="p-6 bg-[#0a0a0a] rounded-2xl border border-red-500/20">
                                    <h4 className="text-sm font-bold text-red-500 mb-2 uppercase tracking-tight">Fechamento de Caixa Diário</h4>
                                    <p className="text-xs text-gray-500 mb-6">Encerre o caixa de hoje e gere o relatório de conciliação.</p>
                                    <Button onClick={() => alert('Caixa fechado com sucesso! Relatório enviado ao e-mail.')} className="w-full bg-red-600/10 text-red-500 border border-red-600/30 hover:bg-red-600 hover:text-white transition-all font-black uppercase tracking-widest text-[10px] py-4">
                                        Fechar Caixa Agora
                                    </Button>
                                </div>
                                <Button variant="outline" className="w-full flex items-center justify-between group">
                                    <span className="text-[10px] uppercase font-black tracking-widest text-gray-400 group-hover:text-white">Ver Relatórios Completos</span>
                                    <Icon name="ExternalLink" className="w-4 h-4 text-[#D4AF37]" />
                                </Button>
                            </div>
                        </section>
                    </div>
                )}
            </div>

            {isExpenseModalOpen && (
                <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
                    <div className="absolute inset-0 bg-black/80 backdrop-blur-sm" onClick={() => setIsExpenseModalOpen(false)} />
                    <div className="relative w-full max-w-md bg-[#111111] border border-[#1f1f1f] rounded-3xl p-8 shadow-2xl animate-fade-in-up">
                        <header className="flex justify-between items-center mb-8">
                            <h2 className="text-xl font-bold">Nova Despesa</h2>
                            <button onClick={() => setIsExpenseModalOpen(false)}><Icon name="X" className="text-gray-500" /></button>
                        </header>
                        <form onSubmit={addExpense} className="space-y-6">
                            <Input value={expenseName} onChange={(e) => setExpenseName(e.target.value)} placeholder="Descrição" className="bg-[#1a1a1a] border-[#222]" />
                            <Input value={expenseValue} onChange={(e) => setExpenseValue(e.target.value)} placeholder="Valor (R$)" type="number" className="bg-[#1a1a1a] border-[#222]" />
                            <Button type="submit" className="w-full bg-red-600 hover:bg-red-700 font-bold uppercase tracking-widest">Lançar Despesa</Button>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
}
